def evaluate_bracket_keys(s, knowledge):
 known=dict(knowledge);answer=[];index=0
 while index<len(s):
  if s[index]=='(':
   end=s.find(')',index+1);answer.append(known.get(s[index+1:end],'?'));index=end+1
  else:answer.append(s[index]);index+=1
 return ''.join(answer)

